    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);

    const response0 = await signIn(page, "admin@example.com", "admin");
    expect(response0.status()).toBe(200);

    await dismissProjectOwnerDialog(page);

    await expect(page.getByRole("button", { name: "Invoices" })).toHaveCount(1);
    await expect(page.getByRole("button", { name: "Marketing" })).toHaveCount(1);
    await expect(page.getByRole("button", { name: "Photos" })).toHaveCount(1);

    await searchFolders(page, "zzzznomatch");
    await expect(page.getByRole("searchbox", { exact: true, name: "Search" })).toHaveValue("zzzznomatch");

